// One-Hot Control unitmodule Controller_BEH_1Hot(  output 		Ready,   output reg 	Load_regs,   output 		Incr_R2, Shift_left,   input 		Start, Zero, E, clock, reset_b);  parameter S_idle = 4'b001, S_1 = 4'b0010, S_2 = 4'b0100, S_3 = 4'b1000;  reg [3:0] state, next_state;  assign Ready = (state == S_idle);  assign Incr_R2 = (state == S_1);  assign Shift_left = (state == S_2);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) state <= S_idle;    else state <= next_state;  always @ (state, Start, Zero, E) begin    Load_regs = 0;    case (state)      S_idle:	if (Start) begin Load_regs = 1; next_state = S_1; end 			else next_state = S_idle;      S_1:	if (Zero) next_state = S_idle; else next_state = S_2;	      S_2:	next_state = S_3;      S_3:	if (E) next_state = S_1; else next_state = S_2;    endcase  endendmodule